
import matplotlib.pyplot as plt
import numpy as np
from pathlib import Path as path


# ============================================================
# DATA IMPORT
# ============================================================

# Resolve the directory containing this script.
folder = path(__file__).resolve().parent

# Locate the CSV generated by the C++ Lyapunov parameter sweep.
csv_file = folder / "lyapunov_plotting.csv"

# Load the numerical data, skipping the CSV header.
data = np.loadtxt(
    csv_file,
    delimiter=",",
    skiprows=1
)


# Extract the control parameter and corresponding
# numerically estimated Lyapunov exponents.
r_total = data[:, 0]
lyapunov_exp_total = data[:, 1]


# ============================================================
# LYAPUNOV EXPONENT VISUALISATION
# ============================================================

plt.figure(figsize=(12, 7))

# Plot the estimated Lyapunov exponent against r.
# Each point represents one parameter value.
plt.scatter(
    r_total,
    lyapunov_exp_total,
    s=8,
    marker=".",
    linewidths=1
)


# ------------------------------------------------------------
# ZERO-EXPONENT REFERENCE
# ------------------------------------------------------------

# A Lyapunov exponent of zero is used as a reference
# for distinguishing contracting and expanding behaviour.
plt.axhline(
    y=0,
    color="black",
    linestyle="--",
    linewidth=1,
    label="λ = 0"
)


# ------------------------------------------------------------
# GRAPH CONFIGURATION
# ------------------------------------------------------------

plt.title("ChaosLab - Lyapunov Exponent Diagram")

plt.xlabel("Logistic Map Parameter (r)")
plt.ylabel("Lyapunov Exponent (λ)")

# Restrict the horizontal axis to the parameter sweep range.
plt.xlim(2.5, 4.0)

plt.grid(alpha=0.25)
plt.legend()
plt.tight_layout()


# ============================================================
# OUTPUT
# ============================================================

# Save the generated figure in the script directory.
plt.savefig(
    folder / "lyapunov.png",
    dpi=200
)

# Display the figure.
plt.show()
